import type {VikingProgress} from './VikingProgress';
import {vikingRecordSymbolWins} from './VikingProgress';
import type {SpinResult,Win} from './SlotMain';
export interface VikingValhallaPlayback {
 before:VikingProgress;entered:VikingProgress;after:VikingProgress;
 sectors:(number|null)[];selected:number;won:boolean;award:Win;
}
/** Explicit wheel outcome, not a guess at source sector probabilities.
 * Rune reset is on entry; growth resets on a win. A miss requires its retained
 * balance to be supplied until the original miss-persistence rule is observed.
 * Currency rounding is deliberately not hidden here.
 */
export function vikingValhalla(state:VikingProgress,sectors:readonly (number|null)[],selected:number,nextPattern:readonly number[],missBalance?:number):VikingValhallaPlayback {
 const check=vikingRecordSymbolWins(state,[]),before=check.before;
 if(!check.valhallaEligible)throw Error('Viking Valhalla needs a completed pattern and a collected rune');
 if(sectors.length<2||sectors.some(s=>s!==null&&(!Number.isInteger(s)||s<4||s>8))||!Number.isInteger(selected)||selected<0||selected>=sectors.length)throw Error('Invalid Viking Valhalla wheel');
 const entered=vikingRecordSymbolWins({...before,runes:[]},[]).after;
 const rune=sectors[selected],won=rune!==null&&before.runes.includes(rune);
 if(!won&&(missBalance===undefined||!Number.isFinite(missBalance)||missBalance<0||missBalance>before.growingBonus))throw Error('Viking Valhalla miss requires an explicit balance policy');
 const after=vikingRecordSymbolWins({pattern:[...nextPattern],cleared:[],runes:[],growingBonus:won?0:missBalance!},[]).after;
 const award:Win={line:-1,symbol:'viking-valhalla',cells:[],amount:won?before.growingBonus:0};
 return {before,entered,after,sectors:[...sectors],selected,won,award};
}
/** Separate growth award is outside the symbol-win cap. Pending fractional
 * currency policy cannot accidentally leak into wallet settlement. */
export function vikingWithValhalla(result:SpinResult,wheel:VikingValhallaPlayback):SpinResult {
 if(result.vikingValhalla||result.rounds?.length||!Number.isSafeInteger(wheel.award.amount)||wheel.award.amount<0)throw Error('Viking Valhalla requires a single settled round and integer award');
 if(result.cascades?.[result.cascades.length-1]?.wins.length)throw Error('Viking Valhalla must follow the final no-win board');
 if(!Number.isSafeInteger(result.payout+wheel.award.amount))throw Error('Unsafe Viking Valhalla settlement');
 const wins=[...result.wins,...(wheel.award.amount?[wheel.award]:[])];
 return {...result,wins,payout:result.payout+wheel.award.amount,vikingValhalla:wheel};
}
