import {SlotMain,SlotConfig,SpinResult} from './SlotMain';
import {BET_LEVELS} from './BetLevels';
import {PHOENIX_SYMBOLS,phoenixSymbol as s,phoenixFreeSequence,PhoenixTurn} from './PhoenixFeature';
export class PhoenixPreviewSlot extends SlotMain {
 constructor(private readonly fixture='stack'){super();}
 readonly columns=5;readonly rows=3;readonly mode='lines' as const;readonly paylines:number[][]=[];readonly bets=[...BET_LEVELS];
 readonly config:SlotConfig={id:'billionaire-loop',title:'불사조 연못',subtitle:'PHOENIX POND',tag:'무료 피처 초안',color:'#413050',accent:'#f1c574',description:'5릴 · 25라인 원판 참고\n정원의 종 3개 · 무료 회전\n황금 불사조 연속 WILD 착지\n각 회전 새 위치에서 대체\n4단계 잭팟은 후속 구현',symbols:PHOENIX_SYMBOLS.map((name,i)=>({id:s(name),name:['학','석등','연꽃','분재','A','K','Q','J','10','9','정원 종','불사조 WILD'][i],color:'#f1c574',weight:0,payout:0}))};
 artResource(id:string){if(!this.config.symbols.some(symbol=>symbol.id===id))throw Error('Unknown Phoenix art');return 'slot-art-handcrafted-v1/billionaire-loop/'+id.slice('billionaire-loop-'.length);}
 spin():SpinResult{throw Error('Phoenix draft is free playback only');}
 demoSpin(bet:number):SpinResult{
  if(!this.bets.includes(bet))throw Error('Invalid bet');const blank=()=>Array.from({length:15},(_,cell)=>s(PHOENIX_SYMBOLS[(cell*3+Math.floor(cell/5))%10])),trigger=blank();if(this.fixture==='no-win')return {bet,board:trigger,payout:0,wins:[]};[0,11,14].forEach(cell=>trigger[cell]=s('bell-scatter'));
  const count=this.fixture==='retrigger'?7:5,turns:PhoenixTurn[]=[];
  for(let n=0;n<count;n++){
   const board=blank(),columns=n===0?[2,3,4]:[n%5];columns.forEach(col=>[col,col+5,col+10].forEach(cell=>board[cell]=s('phoenix-wild')));
   if(this.fixture==='split-wild'&&n===0)board[7]=s('lotus');
   if(n===1)board[6]=s('phoenix-wild');const retrigger=this.fixture==='retrigger'&&n===2;if(retrigger)[0,11,14].forEach(cell=>board[cell]=s('bell-scatter'));
   const cells=n===0?[5,6,7,8,9]:[5,6,7];if(n<3)for(const cell of cells)if(board[cell]!==s('phoenix-wild'))board[cell]=s('crane');turns.push({board,wins:n<3?[{line:n,symbol:s('crane'),amount:bet*(n===0?6:1),cells}]:[],extraSpins:retrigger?2:0});
  }
  return phoenixFreeSequence(trigger,[{line:-1,symbol:s('bell-scatter'),cells:[0,11,14],amount:bet*2}],5,turns,bet);
 }
}
