import {TripleCompassSlot} from './TripleCompassSlot';
import {COMPASS_MODES} from './CompassFeature';
/** Local free-play inspection only. Reuses full natural outcomes; no board substitution. */
export function compassAudit(params:URLSearchParams){
 const slot=new TripleCompassSlot(),mode=params.get('audit-compass'),outcome=params.get('audit-outcome');
 const find=(bet:number,feature:boolean)=>{
  let seed=313140;const rng=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};
  for(let i=0;i<100000;i++){
   const result=slot.spin(bet,rng);
   if(feature){if(result.rounds?.[1].compassFeature?.mode===mode)return result;}
   else if(!result.rounds&&(outcome==='no-win'?result.wins.length===0:result.wins.length>1))return result;
  }
  throw Error('Compass audit outcome not found');
 };
 if(outcome==='no-win'||outcome==='multi-win')slot.demoSpin=bet=>find(bet,false);
 if(mode&&COMPASS_MODES.includes(mode as any))slot.bonusDemoSpin=bet=>find(bet,true);
 return slot;
}
