import type {SpinResult,Win} from './SlotMain';
import {RoadCar,RoadPlan,roadTravelPlan} from './RoadRules';
export const ROAD_ART=['rearview_mirror','charging_phone','air_freshener','flat_tire','coffee_cup','driver_blue','driver_purple','driver_green','driver_ochre','driver_coral','yellow_car','red_car','green_car','collision_wild','traffic_light','mystery_box'];
export const ROAD_EFFECT_ART=['collision_puff','left_motion','right_motion','engine_smoke'];
export const roadSymbol=(name:string)=>'road-rage-x-'+name;
export interface RoadHold {cell:number;symbol:string;value:number}
export interface RoadPlayback {
 rows:number;before:string[];after:string[];cars:RoadCar[];plan:RoadPlan;
 valuesBefore:number[];valuesAfter:number[];heldBefore:RoadHold[];heldAfter:RoadHold[];
 passed:{cell:number;before:number;after:number}[];
}
/** The geometry contract is shared with the manufacturer-rule draft. Supplied
 * awards are explicit audit inputs until connected-99-ways/paytable are verified.
 * No source probability, prize, or natural result is fabricated here. */
export function roadPlayback(rows:number,board:string[],cars:RoadCar[],held:RoadHold[],values:number[],awards:Win[],bet:number):SpinResult{
 if(board.length!==rows*5||values.length!==board.length||values.some(value=>!Number.isSafeInteger(value)||value<1))throw Error('Invalid Road display board');
 const heldCells=new Set<number>();
 for(const hold of held){if(!Number.isInteger(hold.cell)||hold.cell<0||hold.cell>=board.length||heldCells.has(hold.cell)||board[hold.cell]!==hold.symbol||values[hold.cell]!==hold.value)throw Error('Road held state mismatch');heldCells.add(hold.cell);}
 if(cars.some(car=>heldCells.has(car.cell)))throw Error('New Road car overlaps held symbol');
 const blockers=board.flatMap((symbol,cell)=>symbol===roadSymbol('traffic_light')||symbol===roadSymbol('mystery_box')||heldCells.has(cell)?[cell]:[]);
 const plan=roadTravelPlan(rows,cars,blockers),after=[...board],valuesAfter=[...values],heldAfter=held.map(hold=>({...hold})),passed:RoadPlayback['passed']=[];
 const destinations=new Set<number>();
 for(const travel of plan.travel){
  const car=cars.find(car=>car.cell===travel.from)!;
  if(travel.stop==='stationary')continue;
  for(const cell of travel.path.slice(1,-1)){
   const before=valuesAfter[cell],afterValue=before+1;valuesAfter[cell]=afterValue;passed.push({cell,before,after:afterValue});
  }
  after[travel.from]=roadSymbol('collision_wild');valuesAfter[travel.from]=Math.max(1,car.multiplier);
  if(travel.stop==='collision')continue;
  if(destinations.has(travel.to))throw Error('Ambiguous simultaneous Road destination');destinations.add(travel.to);
  after[travel.to]=car.sticky?roadSymbol(car.color+'_car'):roadSymbol('collision_wild');valuesAfter[travel.to]=Math.max(1,car.multiplier);
  if(car.sticky)heldAfter.push({cell:travel.to,symbol:after[travel.to],value:valuesAfter[travel.to]});
 }
 for(const collision of plan.collisions){
  after[collision.cell]=roadSymbol('collision_wild');valuesAfter[collision.cell]=Math.max(1,collision.multiplier);
  if(collision.sticky)heldAfter.push({cell:collision.cell,symbol:after[collision.cell],value:valuesAfter[collision.cell]});
 }
 const wins=awards.map(win=>({...win,cells:[...win.cells]}));
 if(wins.some(win=>!Number.isSafeInteger(win.amount)||win.amount<0||win.cells.some(cell=>!Number.isInteger(cell)||cell<0||cell>=board.length)))throw Error('Invalid Road audit award');
 const feature:RoadPlayback={rows,before:[...board],after,cars:cars.map(car=>({...car})),plan,valuesBefore:[...values],valuesAfter,heldBefore:held.map(hold=>({...hold})),heldAfter,passed};
 return {bet,board:[...after],openingBoard:[...board],symbolValues:[...valuesAfter],heldAtStart:feature.heldBefore,roadFeature:feature,wins,payout:wins.reduce((sum,win)=>sum+win.amount,0)};
}
