import {ExpansionSlot,ExpansionFrame,Geometry,expansionCells as cells,randomIndex} from './ExpansionCore';
import {ExpansionSpec} from './ExpansionCatalog';
import {SpinResult} from './SlotMain';
export const BINGO_LINES=[...Array.from({length:5},(_,r)=>Array.from({length:5},(_,c)=>r*5+c)),...Array.from({length:5},(_,c)=>Array.from({length:5},(_,r)=>r*5+c)),[0,6,12,18,24],[4,8,12,16,20]];
/** Five-by-five money board; packed half-bet units keep each wager's progress isolated. */
export class RabbitBingoSlot extends ExpansionSlot {
 constructor(spec:ExpansionSpec){super(spec);this.paylines.splice(0,this.paylines.length,...Array.from({length:5},(_,r)=>Array.from({length:5},(_,c)=>r*5+c)));const seen=new Set(this.paylines.map(p=>p.join(',')));for(let code=0;this.paylines.length<25&&code<3125;code++){let n=code;const rows=Array.from({length:5},()=>{const r=n%5;n=Math.floor(n/5);return r;});if(rows.some((r,c)=>c>0&&Math.abs(r-rows[c-1])>1))continue;for(const rs of [rows,rows.map(r=>4-r)]){const line=rs.map((r,c)=>r*5+c),key=line.join(',');if(!seen.has(key)&&this.paylines.length<25){seen.add(key);this.paylines.push(line);}}}}
 draw(bet:number,rng:()=>number,g:Geometry=this.geometry){if(!this.bets.includes(bet))throw Error('Invalid bet');const out:string[]=[];for(let c=0;c<g.columns*g.rows;c++){const pool=this.config.symbols.filter(s=>s.weight>0&&!(s.id===this.id('scatter')&&out.some((id,i)=>i%5===c%5&&id===this.id('scatter'))));let roll=rng()*pool.reduce((n,s)=>n+s.weight,0),id=pool[pool.length-1].id;for(const item of pool){roll-=item.weight;if(roll<0){id=item.id;break;}}out.push(id);}return out;}
 get bonusCalibrationKey(){return this.config.id+':expansion-v2-bingo';}
 decode(input:number[]){if(input.length===1)return Array.from({length:25},(_,i)=>i===12?0:(input[0]>>i&1));return Array.from({length:25},(_,i)=>i===12?0:Math.min(1000,Math.floor((input[Math.floor(i/2)]||0)/(i%2?1024:1))%1024));}
 encode(values:number[]){return Array.from({length:13},(_,i)=>(values[i*2]||0)+(values[i*2+1]||0)*1024);}
 private panel(values:number[],bet:number,active:number[]=[],collectIndex?:number){return{label:'BINGO POINTS',values:[...values],columns:5,active,collectIndex};}
 private bingoRound(board:string[],bet:number,rng:()=>number,values:number[]):SpinResult {
  const frames:ExpansionFrame[]=[this.frame(board,'reels','빙고 릴 착지',[],{panel:this.panel(values,bet)}),this.hit(board,bet,'25라인 당첨')];
  const balls=board.flatMap((id,c)=>['coin','double','wheel','jackpot'].some(n=>id===this.id(n))?[c]:[]);
  for(const c of balls){if(c===12)continue;const before=values[c];let add=0;
   if(board[c]===this.id('double'))add=before;
   else if(board[c]===this.id('wheel')){add=[4,6,10,20][randomIndex(rng,4)];frames.push(this.frame(board,'reveal','빙고 휠 · '+add+'점',[c],{panel:this.panel(values,bet,[c]),wheel:{label:'빙고 상금 휠',values:[4,6,10,20],unit:'feature',stage:'first',labels:['4P','6P','10P','20P'],selected:[4,6,10,20].indexOf(add)}}));}
   else if(board[c]===this.id('jackpot'))add=[20,50,100,200][randomIndex(rng,4)];
   else add=[1,2,4,6,10][randomIndex(rng,5)];
   if(!add)continue;values[c]=Math.min(1000,before+add);
   frames.push(this.frame(board,'collect',board[c]===this.id('double')?'같은 위치 빙고 상금 두 배':'상금 공 → 같은 위치 빙고 칸',[c],{panel:this.panel(values.map((v,i)=>i===c?before:v),bet,[c],c),meter:{label:'빙고 점수',before,after:values[c],target:1000,items:[{cell:c,value:values[c]-before}]}}));
  }
  const complete=BINGO_LINES.filter(line=>line.every(c=>c===12||values[c]>0));
  if(complete.length){const paid=Array.from(new Set(complete.flat())).filter(c=>c!==12),sum=paid.reduce((n,c)=>n+values[c],0);frames.push(this.frame(board,'trigger','빙고 '+complete.length+'줄 · 겹친 칸은 한 번 지급',paid,{panel:this.panel(values,bet,paid)}),this.prize(board,bet,sum/2,paid,'빙고 완성 칸 상금'));paid.forEach(c=>values[c]=0);frames.push(this.frame(board,'state','완성 칸만 비움 · 나머지 상금 보존',[],{panel:this.panel(values,bet)}));}
  else frames.push(this.frame(board,'state','빙고 상금 보존',[],{panel:this.panel(values,bet)}));
  return this.round(bet,frames);
 }
 private playWith(board:string[],bet:number,rng:()=>number,values:number[]){const base=this.bingoRound(board,bet,rng,values),gate=cells(board,this.id('scatter'));if(gate.length<3)return this.finish([base]);base.expansionFeature!.frames.push(this.frame(board,'trigger','황금 알 3개 · 무료 10회',gate,{panel:this.panel(values,bet)}));const rounds=[base];for(let left=9;left>=0;left--){const r=this.bingoRound(this.draw(bet,rng),bet,rng,values);r.freeSpinsRemaining=left;rounds.push(r);}return this.finish(rounds,{freeSpinsAwarded:10,featureOnly:false});}
 play(board:string[],bet:number,rng:()=>number){const values=this.decode(this.state(bet,[0])),result=this.playWith(board,bet,rng,values);return this.progressResult(result,bet,this.encode(values));}
 prepareBonusPurchase(bet:number,rng:()=>number){const board=this.draw(bet,rng);[0,6,12].forEach(c=>board[c]=this.id('scatter'));const values=Array(25).fill(0),base=this.round(bet,[this.frame(board,'trigger','새 빙고판 · 독립 무료 10회',[0,6,12],{panel:this.panel(values,bet)})]),rounds=[base];for(let left=9;left>=0;left--){const r=this.bingoRound(this.draw(bet,rng),bet,rng,values);r.freeSpinsRemaining=left;rounds.push(r);}return this.purchaseFromResult(this.finish(rounds,{freeSpinsAwarded:10,featureOnly:false}));}
}
