import {EXPANSION_SPECS} from './ExpansionCatalog';
import {BET_LEVELS} from './BetLevels';
import {SlotMain,SlotConfig,SpinResult,Win,SlotPresentation} from './SlotMain';
import {WOLF_LINES} from './WolfRules';
import {validateSocialBoard} from './Social1921Rules';
export type SlotProgress=Record<string,number[]>;
export interface ProgressUpdate {key:string;values:number[];}
export const PROGRESS_IDS=[...EXPANSION_SPECS.filter(s=>[2,6,7,8,36,37,38,39,40,49].includes(s.requestNumber)).map(s=>s.id),'gem-pattern-kingdom','life-spark-laboratory','ace-target-club','seven-jewel-dig','tenth-bell-sheriff','golden-city-atlas','crystal-seal-breaker','midnight-ballroom','golden-zodiac-choice','starlit-cast','red-cloak-expedition','angel-devil-contract'];
/** Save data is small, finite and isolated by slot AND wager. Changing wager
 * cannot cash a low-wager collection at a higher value. */
export function validProgressUpdate(value:unknown):value is ProgressUpdate {
 const u=value as ProgressUpdate;if(!u||typeof u.key!=='string'||!Array.isArray(u.values)||u.values.length>16)return false;
 const split=u.key.lastIndexOf(':'),id=u.key.slice(0,split),bet=Number(u.key.slice(split+1)),v=u.values;
 if(!PROGRESS_IDS.includes(id)||!BET_LEVELS.includes(bet)||!v.every(n=>Number.isSafeInteger(n)&&n>=0&&n<=1000000000))return false;
 const addition=EXPANSION_SPECS.find(s=>s.id===id);if(addition){switch(addition.requestNumber){
 case 2:return v.length===4&&v[0]<4&&v[1]<80&&v[2]<10&&v[3]<2;
 case 6:return (v.length===1||v.length===2&&v[1]<3)&&v[0]<511;
 case 7:return v.length===1&&v[0]<6;
 case 8:return v.length===2&&v[0]<=3&&v[1]<10;
 case 36:return v.length===1&&v[0]<33554432||v.length===13&&v.every((n,i)=>n%1024<=1000&&Math.floor(n/1024)<=1000&&(i!==12||n<1024))&&v[6]%1024===0;
 case 37:return v.length===1&&v[0]<12||v.length===3&&v.every(n=>n<=3)&&v.reduce((a,b)=>a+b)<6;
 case 38:return v.length===2&&v[0]<12&&v[1]<10;
 case 39:return v.length===5&&v[0]<5&&v.slice(1).some(n=>n<3);
 case 40:return v.length===1&&v[0]<=999;
 case 49:return v[0]>=20260930&&v[0]<21000101&&v[1]<=3&&(v.length===3?(v[1]===3?v[2]===0:v[2]<[5,10,15][v[1]]):v.length===4&&v[3]===2&&(v[1]===3?v[2]===0:v[2]<[[20,40,60],[2,4,6],[1,2,3],[1,2,3],[1,2,3]][v[0]%5][v[1]]));
 }}
 if(id==='gem-pattern-kingdom')return v.length===9&&v[0]<3&&v[1]<3&&v.slice(2).every(n=>n<128);
 if(id==='life-spark-laboratory')return v.length===2&&v[0]<8&&v[1]===v[0];
 if(id==='ace-target-club')return v.length===1&&v[0]<8;
 if(id==='seven-jewel-dig')return v.length===7&&v.every(n=>n<3);
 if(id==='tenth-bell-sheriff')return v.length===1&&v[0]<10;
 if(id==='golden-city-atlas')return v.length===6&&v.slice(0,4).every(n=>n<=4)&&v.slice(0,4).some(n=>n<4)&&v[4]>=1&&v[5]>=1&&v[4]+v[5]===2+v.slice(0,4).filter(n=>n===4).length;
 if(id==='crystal-seal-breaker')return v.length===1&&v[0]>=1&&v[0]<=32767;
 if(id==='midnight-ballroom')return v.length===3&&v[0]<8&&v[1]<6&&v[2]>=1&&v[2]<=4;
 if(id==='golden-zodiac-choice')return v.length===1&&v[0]<3;
 if(id==='starlit-cast')return v.length===11&&v[0]<5&&v.slice(1,6).every((n,i)=>n<5+i)&&v.slice(6).every(n=>n<=3);
 if(id==='red-cloak-expedition')return v.length===3&&v[0]<3&&v[1]<=1&&v[2]<=2;
 return v.length===4&&v.slice(0,3).every(n=>n<=4)&&v[3]<=100*bet;
}
export function normalizeSlotProgress(input:unknown):SlotProgress{
 const out:SlotProgress={};if(!input||typeof input!=='object'||Array.isArray(input))return out;
 for(const [key,values]of Object.entries(input))if(validProgressUpdate({key,values}))out[key]=[...values as number[]];return out;
}
export const SOCIAL_2230_PAYS=[[1.2,3.2,8],[1,2.4,6],[.8,2,4.8],[.6,1.6,4],[.4,1.2,3.2],[.4,1,2.4],[.4,.8,2],[.4,.8,1.6]];
export function social2230Pays(id:string){const factors:Record<string,number>={'gem-cannon-theatre':2.031,'midnight-ballroom':.815,'golden-zodiac-choice':1.7605,'starlit-cast':.989,'frost-flame-crossroads':2.22,'ember-pinball':1.9565,'red-cloak-expedition':1.55};return SOCIAL_2230_PAYS.map(row=>row.map(n=>n*(factors[id]||1)));}
export function awardLines(config:SlotConfig,board:string[],bet:number,pays:number[][],reverse=false):Win[]{
 return WOLF_LINES.flatMap((original,index)=>{const line=reverse?[...original].reverse():original;let best:Win|undefined;
  for(let n=0;n<8;n++){const cells:number[]=[];for(const c of line){if(board[c]!==config.id+'-'+n&&board[c]!==config.id+'-wild')break;cells.push(c);}if(cells.length<3)continue;const multiplier=pays[n][cells.length-3],amount=Math.round(bet*multiplier);if(!best||amount>best.amount)best={line:index,symbol:config.id+'-'+n,cells,amount,multiplier};}
  return best?[best]:[];
 });
}
export function sumResult(result:SpinResult){result.payout=result.wins.reduce((s,w)=>s+w.amount,0);return result;}
export function packRounds(rounds:SpinResult[],extras:Partial<SpinResult>={}):SpinResult {return sumResult({board:[...rounds[rounds.length-1].board],bet:rounds[0].bet,payout:0,wins:rounds.flatMap(r=>r.wins),rounds,...extras});}
/** Only shared reel/line mechanics. Every subclass owns its feature state. */
export abstract class Social2230LineSlot extends SlotMain {
 readonly usesLocalPayouts=true;readonly columns=5;readonly rows=3;readonly paylines=WOLF_LINES;readonly bets=[...BET_LEVELS];readonly maxWin=10000;
 abstract readonly presentation:SlotPresentation;
 get pays(){return social2230Pays(this.config?.id||'');}
 protected progress:SlotProgress={};selection=0;
 setProgress(value:SlotProgress){this.progress=normalizeSlotProgress(value);}
 protected state(bet:number,fallback:number[]){return [...(this.progress[this.config.id+':'+bet]||fallback)];}
 protected update(bet:number,values:number[]):ProgressUpdate{return{key:this.config.id+':'+bet,values:[...values]};}
 evaluate(board:string[],bet:number):SpinResult {validateSocialBoard(this.config,board,bet,this.bets,15);return sumResult({board:[...board],bet,wins:awardLines(this.config,board,bet,this.pays),payout:0,presentation:this.presentation});}
 protected draw(bet:number,rng:()=>number){if(!this.bets.includes(bet))throw Error('Invalid bet');return this.evaluate(Array.from({length:15},()=>this.pick(rng)),bet);}
 protected namedConfig(id:string,title:string,subtitle:string,names:string[],description:string,color:string,accent:string):SlotConfig{return{id,title,subtitle,tag:'SOCIAL LINES',color,accent,description:'5×3 · 25라인 · 왼쪽부터 3개 이상\n'+description,symbols:names.map((name,n)=>({id:id+'-'+(n===8?'wild':n===9?'scatter':n),name,color:accent,weight:[5,6,7,8,10,12,14,16,2,3][n],payout:n<8?social2230Pays(id)[n][2]:0}))};}
}
export function socialPresentation(signature:string,hitText:string):SlotPresentation{return{evidence:'source-title-pending',anticipationText:'피처를 기다립니다',triggerText:signature,bonusInText:signature,hitText,totalWinText:'총 보상',signature,uiEffect:signature,soundCue:'featureLand',anticipationHold:.3,hitHold:.25,outHold:.4};}
