import {vikingValhalla,vikingWithValhalla} from './VikingValhalla';
import {vikingChargeRound} from './VikingChargeRound';
import {vikingChargeResult} from './VikingChargeResult';
import {vikingStandaloneRagnarokResult} from './VikingRagnarokResult';
import {vikingEffectResult} from './VikingEffectResult';
import {vikingExecuteDestruction,vikingRagnarok,VikingDestructionPlan} from './VikingRagnarok';
import {vikingGiftResult,vikingFreyaGiftResult} from './VikingGift';
import {SlotMain,SlotConfig,SpinResult} from './SlotMain';
import {BET_LEVELS} from './BetLevels';
import {VIKING_SYMBOLS} from './VikingRules';
import {vikingOrdinaryCascade} from './VikingCascade';
import {vikingOrdinaryResult,vikingOrdinarySymbol,vikingSymbol} from './VikingResult';
/** Isolated localhost art/tumble fixture. No natural/purchased spins and no
 * claim that the god/Ragnarok/Valhalla engine has been completed. */
export class VikingPreviewSlot extends SlotMain {
 constructor(private readonly fixture='ordinary'){super();}
 readonly columns=7;readonly rows=7;readonly mode='clusters' as const;
 readonly bets=[...BET_LEVELS];readonly paylines:number[][]=[];
 readonly config:SlotConfig={id:'viking-runecrafty',title:'룬가드 사가',subtitle:'RUNEGUARD SAGA',tag:'일반 연쇄 무료 검수',color:'#263c44',accent:'#4d908e',description:'일반 심볼 7×7 · 연속 2회 당첨과 낙하 검수',symbols:[...VIKING_SYMBOLS,'wild-thor','wild-odin','wild-freya','wild-heimdall'].map((_,i)=>({id:vikingSymbol(i),name:['망치','투구','도끼','목걸이','적색 룬','황색 룬','청색 룬','보라 룬','녹색 룬','WILD','WILD','WILD','WILD'][i],color:'#4d908e',weight:0,payout:0}))};
 spin():SpinResult{throw Error('Viking preview is not a live game');}
 demoSpin(bet:number):SpinResult {
  const quiet=(col:number,row:number)=>1+(col+row)%8;
  const initial=Array.from({length:49},(_,cell)=>quiet(cell%7,Math.floor(cell/7)));
  const effects:Record<string,VikingDestructionPlan>={
   fenrir:{kind:'fenrir',lines:[{cells:[0,8,16],action:'remove'},{cells:[2,10,18],action:'transform'},{cells:[4,12,20],action:'remove'},{cells:[14,22,30],action:'transform'}],target:7},
   jormungandr:{kind:'jormungandr',path:[0,1,2,3,4,5,6,13,12,11,10,9,8,7],converted:[0,1,2,3,4],target:0},
   surtr:{kind:'surtr',groups:[{seed:0,burned:[0,1,7,8],core:[0,7,8],symbol:initial[0]},{seed:4,burned:[4,5,11,12],core:[4,11],symbol:initial[4]},{seed:42,burned:[35,36,42,43],core:[42,43],symbol:initial[42]}]},
   loki:{kind:'loki',removedType:1,transformedType:2,targetType:1},
  };
  if(this.fixture==='valhalla'){
   [42,43,44,45,46].forEach(cell=>initial[cell]=8);
   const progress={pattern:[42,43,44,45,46],cleared:[],runes:[4],growingBonus:0};
   const probe=vikingOrdinaryCascade(initial,bet,quiet,{progress});
   const segment=vikingOrdinaryCascade(initial,bet,quiet,{progress:{...progress,growingBonus:20-probe.progress!.growingBonus}});
   const state=segment.progress!;
   const wheel=vikingValhalla(state,[4,null,5,null,6,null,7,null,8,null],8,[0,1,2,3,4]);
   return vikingWithValhalla(vikingOrdinaryResult(bet,segment),wheel);
  }
  if(this.fixture==='charge'){
   [0,2,4,6].forEach((row,symbol)=>{for(let col=0;col<5;col++)initial[row*7+col]=symbol;});
   return vikingChargeResult(bet,vikingChargeRound(initial,bet,{refill:quiet,plan:()=>effects.jormungandr}));
  }
  if(this.fixture==='ragnarok'||this.fixture==='ragnarok-max'){
   [0,2,4,6].forEach((row,symbol)=>{for(let col=0;col<5;col++)initial[row*7+col]=symbol;});
   if(this.fixture==='ragnarok-max')initial.fill(0);
   let refillCount=0;const refill=this.fixture==='ragnarok-max'?(col:number,row:number)=>refillCount++<49?0:quiet(col,row):quiet;
   const resolved=vikingRagnarok(initial,bet,{refill,plan:(board,remaining)=>{
    const effect=effects[remaining[0]];
    if(effect.kind==='surtr'){const used=new Set<number>();return {kind:'surtr',groups:effect.groups.map(group=>{const seed=group.burned.find(c=>board[c]<9&&!used.has(board[c]));if(seed===undefined)throw Error('Fixture requires distinct Surtr seeds');used.add(board[seed]);return {...group,seed,symbol:board[seed],core:[seed,...group.burned.filter(c=>c!==seed).slice(0,1)]};})};}
    if(effect.kind==='loki'){const [a,b]=[...Array.from(new Set(board))].filter(s=>s<9);return {kind:'loki',removedType:a,transformedType:b,targetType:a};}
    return effect;
   }});
   return vikingStandaloneRagnarokResult(bet,resolved);
  }
  if(effects[this.fixture])return vikingEffectResult(bet,vikingExecuteDestruction(initial,effects[this.fixture],quiet),quiet);
  if(this.fixture==='freya'){
   const growthBoard=[0,0,0,4,8,2,7,8,7,8,5,2,2,5,7,2,5,2,6,5,8,1,2,1,4,2,2,3,7,1,7,5,6,7,7,8,7,4,5,3,8,8,1,3,6,8,6,1,3];
   return vikingFreyaGiftResult(growthBoard,bet,[[8,12,36,40],[9,13,35,41]],quiet);
  }
  if(this.fixture==='gift'){
   [21,22,24,25].forEach(cell=>initial[cell]=0);
   return vikingGiftResult(initial,bet,'thor',[23,6,42,48,0],quiet);
  }
  if(this.fixture==='wild'){
   [21,22,24,25].forEach(cell=>initial[cell]=0);
   initial[23]=9;initial[6]=10;initial[42]=11;initial[48]=12;
   return vikingOrdinaryResult(bet,vikingOrdinaryCascade(initial,bet,quiet));
  }
  if(this.fixture==='progress'){
   [42,43,44,45,46].forEach(cell=>initial[cell]=8);
   return vikingOrdinaryResult(bet,vikingOrdinaryCascade(initial,bet,quiet,{progress:{pattern:[42,43,44,45,46,0],cleared:[0],runes:[4],growingBonus:10}}));
  }
  // Bottom-row hit exercises movement of every survivor above the gaps.
  [42,43,44,45,46].forEach(cell=>initial[cell]=0);
  let refills=0;
  const segment=vikingOrdinaryCascade(initial,bet,(col,row)=>refills++<5?0:quiet(col,row));
  const result=vikingOrdinaryResult(bet,segment);
  if(this.fixture==='god-odin')result.vikingGod='odin';
  if(this.fixture==='god-heimdall')result.vikingGod='heimdall';
  return result;
 }
}
