import {isLocalMode} from './LocalMode';
import {sys} from 'cc';
import {installNativeXHRCompatibility} from './NativeXHRCompatibility';
import {androidGoogleIdToken} from './AndroidGoogleSignIn';
import {initializeApp, getApps, initializeFirestore} from '../vendor/firebase-sdk.js';
import {getAuth, initializeAuth, browserLocalPersistence, setPersistence, onAuthStateChanged,
 signInAnonymously, signInWithPopup, signInWithCredential, linkWithCredential, linkWithPopup, FacebookAuthProvider, GoogleAuthProvider, signOut} from '../vendor/firebase-sdk.js';
import type {FirebaseError} from 'firebase/app';
import type {Auth, AuthProvider, OAuthCredential, User} from 'firebase/auth';
import {firebaseConfig} from './FirebaseConfig';

import {authErrorMessage} from './AuthErrors';
export {authErrorMessage} from './AuthErrors';

export class FirebaseAuth {
 private auth: Auth | null = null;
 private unsubscribe: (() => void) | null = null;
 ready = false;
 error = '';
 get user(): User | null { return this.auth?.currentUser || null; }
 get configured(): boolean { return !!(firebaseConfig.apiKey && firebaseConfig.authDomain && firebaseConfig.projectId && firebaseConfig.appId); }
 get facebookSupported():boolean { return !sys.isNative; }
 async initialize(changed: (user: User | null) => void): Promise<void> {
  if(isLocalMode()){this.ready=false;return;}
  if (!this.configured) { this.error = '로그인 서비스를 준비 중입니다. 잠시 후 다시 방문해 주세요.'; return; }
  try {
   if(sys.isNative)installNativeXHRCompatibility();
   const app = getApps().find(app => app.name === 'in-my-pocket') || initializeApp(firebaseConfig, 'in-my-pocket');
   if(sys.isNative){
    // Cocos has localStorage/XHR, but no browser OAuth popup or fetch streams.
    this.auth = initializeAuth(app,{persistence:browserLocalPersistence});
    initializeFirestore(app,{experimentalForceLongPolling:true,useFetchStreams:false} as any);
   }else this.auth = getAuth(app);
   await setPersistence(this.auth, browserLocalPersistence);
   await this.auth.authStateReady();
   this.ready = true;
   this.unsubscribe = onAuthStateChanged(this.auth, changed);
  } catch (error) { this.error = authErrorMessage(error); }
 }
 guest(): Promise<User> {
  if (!this.auth || !this.ready) return Promise.reject(new Error('Authentication unavailable'));
  // Never silently use a Google account when the user explicitly chooses guest.
  if (this.auth.currentUser?.isAnonymous) return Promise.resolve(this.auth.currentUser);
  if (this.auth.currentUser) return Promise.reject(new Error('Sign out before guest login'));
  return signInAnonymously(this.auth).then(result => result.user);
 }
 google(): Promise<User> {
  if(sys.isNative)return sys.os===sys.OS.ANDROID?this.nativeGoogle():Promise.reject(new Error('Native Google sign-in is unavailable on this platform'));
  const provider = new GoogleAuthProvider();
  provider.setCustomParameters({prompt: 'select_account'});
  return this.social(provider, GoogleAuthProvider.credentialFromError);
 }
 facebook(): Promise<User> {
  if(!this.facebookSupported)return Promise.reject(new Error('이 기기에서는 Google 로그인을 사용해 주세요.'));
  const provider = new FacebookAuthProvider();
  provider.setCustomParameters({display: 'popup'});
  return this.social(provider, FacebookAuthProvider.credentialFromError);
 }
 private async nativeGoogle():Promise<User>{
  if(!this.auth||!this.ready)throw Error('Authentication unavailable');
  const auth=this.auth,guest=auth.currentUser?.isAnonymous?auth.currentUser:null;
  const credential=GoogleAuthProvider.credential(await androidGoogleIdToken());
  try{return (await (guest?linkWithCredential(guest,credential):signInWithCredential(auth,credential))).user;}
  catch(error){
   if(!guest||(error as FirebaseError).code!=='auth/credential-already-in-use'||auth.currentUser?.uid!==guest.uid)throw error;
   return (await signInWithCredential(auth,credential)).user;
  }
 }
 private social(provider: AuthProvider, credentialFromError: (error: FirebaseError) => OAuthCredential | null): Promise<User> {
  if(sys.isNative)return Promise.reject(new Error('Browser sign-in is unavailable in native builds'));
  if (!this.auth || !this.ready) return Promise.reject(new Error('Authentication unavailable'));
  // Start the popup synchronously from the click; no animation/await beforehand.
  const auth = this.auth;
  const guest = auth.currentUser?.isAnonymous ? auth.currentUser : null;
  return (guest ? linkWithPopup(guest, provider) : signInWithPopup(auth, provider))
   .catch(error => {
    // A returning social player uses their existing save; never merge or overwrite it.
    if (!guest || error?.code !== 'auth/credential-already-in-use' || auth.currentUser?.uid !== guest.uid) throw error;
    const credential = credentialFromError(error as FirebaseError);
    if (!credential) throw error;
    return signInWithCredential(auth, credential);
   }).then(result => result.user);
 }
 logout(): Promise<void> { return this.auth ? signOut(this.auth) : Promise.resolve(); }
 dispose(): void { this.unsubscribe?.(); this.unsubscribe = null; }
}
