import {LocalizedNotice,validateNoticeLocalizations} from './NoticeText';
import {WeeklyFreeSpinPlan,validateWeeklyFreeSpinPlan} from './WeeklyFreeSpins';
export interface Notice extends LocalizedNotice {id:string;giftId?:string;}
export interface LivePolicy {notices:Notice[];minimumVersion:Record<string,string>;storeUrls:Record<string,string>;requiredVersion?:Record<string,string>;weeklyFreeSpins?:WeeklyFreeSpinPlan;}
export function compareVersions(a:string,b:string){
 if(!/^\d+(\.\d+){0,3}$/.test(a)||!/^\d+(\.\d+){0,3}$/.test(b))throw Error('잘못된 버전 설정');
 const x=a.split('.').map(Number),y=b.split('.').map(Number);for(let i=0;i<Math.max(x.length,y.length);i++){const d=(x[i]||0)-(y[i]||0);if(d)return Math.sign(d);}return 0;
}
export function validatePolicy(v:any):LivePolicy {
 if(!v||!Array.isArray(v.notices)||v.notices.length>30||!v.minimumVersion||!v.storeUrls)throw Error('운영 설정을 확인해 주세요.');
 const ids=new Set<string>();for(const n of v.notices){if(typeof n.id!=='string'||!n.id||ids.has(n.id)||typeof n.title!=='string'||!n.title||n.title.length>60||typeof n.body!=='string'||n.body.length>3000)throw Error('공지 형식 오류');if(n.giftId!==undefined&&(typeof n.giftId!=='string'||!/^[-a-zA-Z0-9]{1,80}$/.test(n.giftId)))throw Error('선물 연결 오류');validateNoticeLocalizations(n.localizations);ids.add(n.id);}
 for(const platform of ['web','android','ios']){compareVersions(v.minimumVersion[platform],'0');const url=v.storeUrls[platform];if(typeof url!=='string'||(url&&!/^https:\/\/[^\s]+$/.test(url)))throw Error('HTTPS 업데이트 주소가 필요합니다.');if(compareVersions(v.minimumVersion[platform],'0')>0&&!url)throw Error('최소 버전 지정 시 업데이트 주소가 필요합니다.');}
 for(const platform of ['web','android','ios']){const version=v.requiredVersion?.[platform];if(version!==undefined){compareVersions(version,'0');if(compareVersions(version,'0')>0&&!v.storeUrls[platform])throw Error('업데이트 주소가 필요합니다.');}}
 return {...v,...(v.weeklyFreeSpins?{weeklyFreeSpins:validateWeeklyFreeSpinPlan(v.weeklyFreeSpins)}:{})};
}

/** Exact update target takes precedence; old minimum-version policies remain readable. */
export function requiresUpdate(policy:LivePolicy,platform:string,version:string){const target=policy.requiredVersion?.[platform];return target&&compareVersions(target,"0")>0?compareVersions(version,target)!==0:compareVersions(version,policy.minimumVersion[platform])<0;}
