import {ExpansionSlot,ExpansionFrame,expansionCells as cells} from './ExpansionCore';
import {SpinResult} from './SlotMain';
// Native Cocos omits Intl. The game's dates use the US Pacific DST rules
// effective since 2007: second Sunday in March / first Sunday in November.
export const bisonChallengeDay=(time:number)=>{
 const shifted=time-60000,year=new Date(shifted).getUTCFullYear();
 const marchSunday=1+(7-new Date(Date.UTC(year,2,1)).getUTCDay())%7;
 const novemberSunday=1+(7-new Date(Date.UTC(year,10,1)).getUTCDay())%7;
 const summer=shifted>=Date.UTC(year,2,marchSunday+7,10)&&shifted<Date.UTC(year,10,novemberSunday,9);
 const date=new Date(shifted-(summer?7:8)*3600000);
 return date.getUTCFullYear()*10000+(date.getUTCMonth()+1)*100+date.getUTCDate();
};
const TIERS=['BRONZE','SILVER','GOLD','COMPLETE'];
/** Daily event counters follow the official rules; targets/prizes and free-spin math are local. */
export class BisonDailySlot extends ExpansionSlot {
 day=()=>bisonChallengeDay(Date.now());
 constructor(spec:ConstructorParameters<typeof ExpansionSlot>[0]){super(spec);for(const name of ['bronze','silver','gold','day'])this.config.symbols.push({id:this.id(name),name,color:'#dab263',weight:0,payout:0});this.config.description='5×4 · 1,024 WAYS · 왼쪽부터 연결\nBONUS 3개 이상: 무료 8회. 무료 중 재발동 +8회, 최대 120회.\n베팅별 BRONZE → SILVER → GOLD 일일 도전. 일반 회전의 지정 심볼·3/4연속 조합·보너스 진입·10배 이상 당첨을 셉니다.\n무료 회전과 구매는 일일 도전에 포함되지 않습니다. 태평양 시간 00:01에 새 도전으로 초기화됩니다.\n목표·상금·확률은 로컬 규칙입니다. 구매는 일일 진행과 별개인 독립 무료 8회입니다.';}
 get bonusCalibrationKey(){return this.config.id+':expansion-v2-daily';}
 challenge(day:number,tier:number){const kind=day%5,symbol=Math.floor(day/5)%8,target=([ [20,40,60],[2,4,6],[1,2,3],[1,2,3],[1,2,3] ][kind])[Math.min(2,tier)];return{kind,symbol,target};}
 dailyState(bet:number){const day=this.day(),saved=this.state(bet,[]);return saved.length===4&&saved[0]===day&&saved[3]===2&&Number.isInteger(saved[1])&&saved[1]>=0&&saved[1]<=3&&Number.isSafeInteger(saved[2])&&saved[2]>=0?saved:[day,0,0,2];}
 private contribution(board:string[],base:SpinResult,kind:number,symbol:number){
  if(kind===0){const found=cells(board,this.id(symbol));return{value:found.length,cells:found};}
  if(kind===3){const found=cells(board,this.id('scatter'));return{value:Number(found.length>=3),cells:found};}
  if(kind===4)return{value:Number(base.payout>=base.bet*10),cells:Array.from(new Set(base.wins.flatMap(w=>w.cells)))};
  const groups:number[][]=[];for(let col=0;col<5;col++){const g=board.flatMap((s,c)=>c%5===col&&(s===this.id(symbol)||this.isWild(s))?[c]:[]);if(!g.length)break;groups.push(g);}const found=groups.flat(),need=kind===1?3:4;
  return{value:groups.length===need&&found.some(c=>board[c]===this.id(symbol))?groups.reduce((n,g)=>n*g.length,1):0,cells:found};
 }
 private freeGames(base:SpinResult,bet:number,rng:()=>number){return this.freeFromRound(base,bet,rng,8,b=>{const r=this.ordinary(b,bet,'들소 무료 회전 · 일일 도전 제외');if(cells(b,this.id('scatter')).length>=3)r.freeSpinsAdded=8;return r;},cells(base.board,this.id('scatter')),120);}
 play(board:string[],bet:number,rng:()=>number){
  this.validate(board,bet);const state=this.dailyState(bet),tier=state[1],challenge=this.challenge(state[0],tier),base=this.ordinary(board,bet,'들소 행로 · 1,024 WAYS'),fs=base.expansionFeature!.frames;
  const view=(count:number,complete=false)=>({tier,count,target:challenge.target,kind:challenge.kind,symbol:this.id(challenge.symbol),complete});
  fs.forEach(f=>f.bisonDaily=view(state[2]));
  if(tier<3){const earned=this.contribution(board,base,challenge.kind,challenge.symbol),before=state[2];state[2]=Math.min(challenge.target,before+earned.value);
   if(earned.value)fs.push(this.frame(board,'collect',TIERS[tier]+' · 조건 달성 +'+earned.value,earned.cells,{bisonDaily:view(state[2]),meter:{label:TIERS[tier],before,after:state[2],target:challenge.target,items:earned.cells.map(cell=>({cell,value:1}))}}));
   if(state[2]>=challenge.target){fs.push(this.frame(board,'trigger',TIERS[tier]+' 완료 · 메달 보상',earned.cells,{bisonDaily:view(state[2],true),actor:{symbol:this.id(['bronze','silver','gold'][tier]),cells:earned.cells}}));const prize=this.prize(board,bet,[.5,1,2][tier],[],TIERS[tier]+' 일일 상금');prize.bisonDaily=view(state[2],true);fs.push(prize);state[1]++;state[2]=0;}
  }
  // Rebuild aggregate after adding challenge wins; frames remain the single settlement source.
  const settled=this.round(bet,fs),result=cells(board,this.id('scatter')).length>=3?this.freeGames(settled,bet,rng):this.finish([settled]);for(const r of result.rounds||[result])for(const f of r.expansionFeature!.frames)if(!f.bisonDaily)f.bisonDaily={tier:state[1],count:state[2],target:state[1]<3?this.challenge(state[0],state[1]).target:0,kind:challenge.kind,symbol:this.id(challenge.symbol),complete:false};return this.progressResult(result,bet,state);
 }
 prepareBonusPurchase(bet:number,rng:()=>number){for(let i=0;i<50000;i++){const b=this.draw(bet,rng),gates=cells(b,this.id('scatter'));if(gates.length>=3)return this.purchaseFromResult(this.freeGames(this.round(bet,[this.frame(b,'trigger','독립 들소 무료 8회',gates)]),bet,rng));}throw Error('Bison free gate unavailable');}
}
