import {AceTargetSlot} from './AceTargetSlot';import {socialSeed} from './Social1921Rules';
export function aceTargetAudit(params:URLSearchParams){const slot=new AceTargetSlot(),outcome=params.get('audit-outcome')||'target';if(outcome==='no-win'||outcome==='multi-win'||outcome==='collect')slot.demoSpin=bet=>{const rng=socialSeed(460321);for(let i=0;i<30000;i++){const r=slot.spin(bet,rng);if(!r.rounds&&(outcome==='no-win'?!r.payout:outcome==='multi-win'?r.wins.length>1:r.aceFeature!.collected.length>0))return r;}throw Error('Ace fixture unavailable');};return slot;}
