import type {SpinResult} from './SlotMain';
/** Purchases already contain only free-game rounds. Natural entries retain
 * their paid trigger round, which must not be counted again as a free spin. */
export function bonusCompletion(result:SpinResult,purchased:boolean){
 if(!result.rounds?.length)return null;
 const bonusRounds=purchased?result.rounds:result.rounds.slice(1),counted=bonusRounds.filter(round=>(!round.moonFeature||round.moonFeature.mode==='free')&&round.crossroadsFeature?.mode!=='wheel');
 if(!counted.length)return null;
 return{count:counted.length,payout:bonusRounds.reduce((sum,round)=>sum+round.payout,0)};
}
