import type {ExpansionFrame} from '../slots/ExpansionCore';

export interface BonusEntryValueReveal {cell:number;value:number;}

/** Values already present when a bonus board opens are introduced separately.
 * Reel/drop frames own their landing reveal, and Dragon Vault has bespoke entry
 * choreography, so neither may be replayed by the generic entry sequence. */
export function bonusEntryValueReveals(frame:ExpansionFrame|undefined):BonusEntryValueReveal[]{
 if(!frame||frame.action==='reels'||frame.action==='drop'||frame.dragonVault?.entryCells?.length)return [];
 const byCell=new Map<number,number>();
 for(const award of frame.coinAwards||[]){
  const value=Math.round(award.win.amount*(award.fraction??1));
  if(Number.isInteger(award.cell)&&award.cell>=0&&award.cell<frame.board.length&&frame.board[award.cell]&&value>0)byCell.set(award.cell,value);
 }
 if(!byCell.size)for(const [cell,value]of (frame.values||[]).entries()){
  // A value of one is also used as a split/count marker in ordinary games.
  // Higher values on a non-reel entry frame are actual visible multipliers.
  if(frame.board[cell]&&Number.isFinite(value)&&value>1)byCell.set(cell,value);
 }
 return [...byCell].sort(([a],[b])=>a-b).map(([cell,value])=>({cell,value}));
}

/** User-approved cadence for every initial prize reveal, never quick-stop scaled. */
export function bonusEntryValueRevealInterval(_count:number,_slotId?:string){
 return .5;
}

/** Diamond collectors copy prizes on their own 5x3 board; fixed Four Cart pots are excluded. */
export function coinGrabTargets(frame:ExpansionFrame|undefined):number[]{
 if(!frame?.coinAwards||!frame.board.some(id=>id==='four-cart-gold-diamond'||id==='harvest-moon-fiesta-diamond'))return [];
 return frame.coinAwards.filter(a=>frame.board[a.cell]?.endsWith('-diamond')).map(a=>a.cell).sort((a,b)=>a-b);
}
export function coinGrabSources(frame:ExpansionFrame,target:number,visibleValues:readonly number[]){
 const panel=(cell:number)=>frame.columns===10?Math.floor(Math.floor(cell/10)/3)*2+Math.floor(cell%10/5):0;
 return (frame.coinAwards||[]).filter(a=>a.cell!==target&&panel(a.cell)===panel(target)&&visibleValues[a.cell]>0&&frame.board[a.cell]!=='four-cart-gold-multi').sort((a,b)=>a.cell-b.cell);
}
