import {SevenJewelSlot} from './SevenJewelSlot';
export function sevenJewelAudit(params:URLSearchParams){const slot=new SevenJewelSlot(),outcome=params.get('audit-outcome');if(outcome)slot.demoSpin=bet=>{let seed=389281;const rng=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};slot.setProgress({});for(let i=0;i<200000;i++){const r=slot.spin(bet,rng),f=r.jewelFeature!,events=f.stages.flatMap(s=>s.gems),match=outcome==='match'?events.some(e=>e.matched):outcome==='mystery'?events.some(e=>e.matched&&e.jewel===6):outcome==='collect'?events.length>0:outcome==='tumble'?f.stages.length>=3:outcome==='no-win'?r.wins.length===0:outcome==='single-win'?r.wins.length>0&&new Set(r.wins.map(w=>w.symbol)).size===1:outcome==='multi-win'?new Set(r.wins.map(w=>w.symbol)).size>1:false;if(match)return r;slot.setProgress({[r.progressUpdate!.key]:r.progressUpdate!.values});}throw Error('Jewel natural sequence unavailable');};return slot;}
