import {BlockInputEvents,Color,Graphics,Node,UITransform} from 'cc';

/** Shared modal treatment: black enough to focus the card while keeping its context visible. */
export const MODAL_BACKDROP_OPACITY=128;
export const MODAL_BACKDROP_SCALE=2;

/** Adds a centered, input-blocking backdrop as the parent's first popup layer. */
export function addModalBackdrop(parent:Node,width:number,height:number,name:string,onTap?:()=>void){
 const backdrop=new Node(name);backdrop.layer=parent.layer;parent.addChild(backdrop);
 backdrop.addComponent(UITransform);
 resizeModalBackdrop(backdrop,width,height);
 backdrop.addComponent(BlockInputEvents);
 backdrop.on(Node.EventType.TOUCH_END,(event:any)=>{event.propagationStopped=true;onTap?.();});
 return backdrop;
}

/** Resize the draw and hit area together, overscanning the viewport without scaling the popup. */
export function resizeModalBackdrop(backdrop:Node,width:number,height:number){
 width*=MODAL_BACKDROP_SCALE;height*=MODAL_BACKDROP_SCALE;
 const bounds=backdrop.getComponent(UITransform)!;
 if(backdrop.getComponent(Graphics)&&bounds.width===width&&bounds.height===height)return;
 bounds.setContentSize(width,height);
 const graphic=backdrop.getComponent(Graphics)||backdrop.addComponent(Graphics);
 // Keep alpha on the draw color, independent of popup/card animations.
 graphic.clear();graphic.fillColor=new Color(0,0,0,MODAL_BACKDROP_OPACITY);
 graphic.rect(-width/2,-height/2,width,height);graphic.fill();
}
