import {SlotMain,SpinResult} from './SlotMain';
import {mathAcceptance,mathClasses} from './MathPolicyConfig';
export const mathTargets={rtp:.98,bigWin:.0175,feature:.0175,baseHit:.40};
const edges=[0,.1,.25,.5,1,2,5,10,20,30,50,100,200,500,1000,Infinity];
export function mathBin(r:SpinResult){const multiple=r.payout/r.bet;const bucket=multiple===0?0:edges.findIndex(edge=>edge>multiple)+1;return `${Number(!!r.rounds&&r.rounds.length>1)}:${Number((r.rounds?.[0]||r).payout>0)}:${Number((r.rounds?.[0]||r).payout>=r.bet*10)}:${bucket}`;}
export function mathKey(slot:SlotMain,bet:number){const choice=(slot as SlotMain&{bonusChoice?:number}).bonusChoice;return slot.config.id+(choice===undefined?'':':'+choice)+'@'+bet;}
/** Fixed distribution, independent of player balances, history and purchases. Retains evaluated boards and their full payouts. */
export function balancedSpin(slot:SlotMain,bet:number,rng:()=>number,sample:()=>SpinResult){
 const policy=mathAcceptance[mathKey(slot,bet)];if(!policy)throw Error('Missing math calibration: '+mathKey(slot,bet));
 const groups=Object.entries(mathClasses[mathKey(slot,bet)]);let roll=rng();let selected=groups[groups.length-1];
 for(const group of groups){roll-=group[1].probability;if(roll<0){selected=group;break;}}
 for(let i=0;i<20000;i++){const r=sample(),bin=mathBin(r);if(bin.slice(0,bin.lastIndexOf(':'))===selected[0]&&rng()<(policy[bin]??0)/selected[1].ceiling)return r;}
 // A very rare joint class must not stall the game. Fallback still uses the same fitted legal-outcome distribution.
 for(let i=0;i<10000;i++){const r=sample();if(rng()<(policy[mathBin(r)]??0))return r;}
 throw Error('Unable to sample a balanced outcome');
}
