import {VikingOrdinaryAward,VIKING_PAYS,VIKING_THRESHOLDS} from './VikingRules';

/** Provider Game Help: all four god WILDs substitute every ordinary symbol.
 * Overlapping payable WILD groups and pure-WILD awards still need observation;
 * reject those actual ambiguous boards instead of silently inventing priority.
 */
export function vikingClusters(board:readonly number[],bet:number):VikingOrdinaryAward[]{
 if(board.length!==49||board.some(s=>!Number.isInteger(s)||s<0||s>12)||!Number.isSafeInteger(bet)||bet<=0)throw Error('Invalid Viking cluster board or stake');
 const adjacent=(cell:number)=>[...(cell%7>0?[cell-1]:[]),...(cell%7<6?[cell+1]:[]),...(cell>=7?[cell-7]:[]),...(cell<42?[cell+7]:[])];
 function groups(accept:(symbol:number)=>boolean){
  const seen=new Set<number>(),groups:number[][]=[];
  for(let cell=0;cell<49;cell++){
   if(seen.has(cell)||!accept(board[cell]))continue;
   const cells=[cell];seen.add(cell);
   for(let head=0;head<cells.length;head++)for(const next of adjacent(cells[head])){
    if(!seen.has(next)&&accept(board[next])){seen.add(next);cells.push(next);}
   }
   groups.push(cells.sort((a,b)=>a-b));
  }
  return groups;
 }
 if(groups(symbol=>symbol>=9).some(cells=>cells.length>=5))throw Error('Viking pure-WILD award requires source verification');
 const awards:VikingOrdinaryAward[]=[],usedWild=new Set<number>();
 for(let symbol=0;symbol<9;symbol++)for(const cells of groups(s=>s===symbol||s>=9)){
  if(cells.length<5||!cells.some(cell=>board[cell]===symbol))continue;
  const wilds=cells.filter(cell=>board[cell]>=9);
  if(wilds.some(cell=>usedWild.has(cell)))throw Error('Viking overlapping WILD awards require source verification');
  wilds.forEach(cell=>usedWild.add(cell));
  let tier=0;while(tier+1<VIKING_THRESHOLDS.length&&cells.length>=VIKING_THRESHOLDS[tier+1])tier++;
  const multiple=VIKING_PAYS[symbol][tier];awards.push({symbol,cells,multiple,amount:bet*multiple});
 }
 return awards;
}
