/** Wolf Gold's original single-board Money Respin state machine.
 * Source: docs/slots/wolf-gold-moon.md. Value set confirmed from original
 * help page 3/7; probabilities remain caller supplied and are not original strips.
 * Fixed cell coordinates are retained for sticky rendering during every spin. */
export interface WolfMoneyToken {cell:number;multiple:number;kind:'cash'|'mini'|'major';}
export const WOLF_MONEY_VALUES:readonly number[]=[1,2,3,4,5,6,7,8,10,14,16,18,20,24,30,100];
export const WOLF_JACKPOTS={mini:30,major:100,mega:1000} as const;
export interface WolfMoneyState {
 tokens:WolfMoneyToken[];
 remaining:number;
 complete:boolean;
 collected:boolean;
}
export interface WolfMoneyStep {
 before:WolfMoneyState;
 after:WolfMoneyState;
 landed:WolfMoneyToken[];
}
const copy=(s:WolfMoneyState):WolfMoneyState=>({...s,tokens:s.tokens.map(t=>({...t}))});
function validateTokens(tokens:readonly WolfMoneyToken[]){
 const cells=new Set<number>();
 for(const token of tokens){
  if(!Number.isInteger(token.cell)||token.cell<0||token.cell>=15||cells.has(token.cell)||
   !WOLF_MONEY_VALUES.includes(token.multiple)||!['cash','mini','major'].includes(token.kind)||
   token.kind==='mini'&&token.multiple!==WOLF_JACKPOTS.mini||token.kind==='major'&&token.multiple!==WOLF_JACKPOTS.major)throw Error('Invalid Wolf money token');
  cells.add(token.cell);
 }
}
function validateState(state:WolfMoneyState){
 validateTokens(state.tokens);
 if(state.tokens.length<6||!Number.isInteger(state.remaining)||state.remaining<0||state.remaining>3||
  state.complete!==(state.remaining===0||state.tokens.length===15)||state.collected&&!state.complete)throw Error('Invalid Wolf money state');
}
export function wolfMoneyStart(tokens:readonly WolfMoneyToken[]):WolfMoneyState{
 validateTokens(tokens);
 if(tokens.length<6)throw Error('Wolf money requires six triggering symbols');
 return {tokens:tokens.map(t=>({...t})),remaining:tokens.length===15?0:3,complete:tokens.length===15,collected:false};
}
export function wolfMoneyRespin(state:WolfMoneyState,landed:readonly WolfMoneyToken[]):WolfMoneyStep{
 validateState(state);validateTokens(landed);
 if(state.complete)throw Error('Wolf money round has ended');
 const held=new Set(state.tokens.map(t=>t.cell));
 if(landed.some(t=>held.has(t.cell)))throw Error('Cannot overwrite a held Wolf money symbol');
 const tokens=[...state.tokens,...landed].map(t=>({...t}));
 const remaining=tokens.length===15?0:landed.length?3:state.remaining-1;
 return {before:copy(state),after:{tokens,remaining,complete:remaining===0,collected:false},landed:landed.map(t=>({...t}))};
}
export function wolfMoneyCollect(state:WolfMoneyState,bet:number){
 validateState(state);
 if(!state.complete||state.collected)throw Error('Wolf money is not ready to collect');
 if(!Number.isSafeInteger(bet)||bet<=0)throw Error('Invalid Wolf bet');
 const moneyMultiple=state.tokens.reduce((sum,t)=>sum+t.multiple,0);
 const moneyPayout=Math.round(moneyMultiple*bet),megaPayout=state.tokens.length===15?WOLF_JACKPOTS.mega*bet:0;
 if(!Number.isSafeInteger(moneyPayout+megaPayout))throw Error('Wolf money payout overflow');
 return {state:{...copy(state),collected:true},moneyMultiple,moneyPayout,megaPayout,payout:moneyPayout+megaPayout};
}
