import type {SlotMain} from './SlotMain';

// Explicit gameplay roles, never inferred from translated names or payout size.
// Some symbols (wagon rewards, for example) are created by feature playback.
const roles:Record<string,readonly string[]>={
 'gladiator-lore':['duel_swords','arena_gate','beast_gate','normal_token','epic_token','lion'],
 'chaos-crew-x':['cat_wild','scatter_poster','bonus_skull','epic_skull','bonus_cat','epic_cat'],
 'itero-core':['hand','add','multiply'],
 'le-raccoon-bandit':['rainbow'],
 'crypt-of-x':['mystery'],
 'tome-of-madness':['multiplier','mega'],
 'moon-princessa':['0','1','2'],
 'rhino-grand-ways':['10','11'],
 'wolf-gold-moon':['money'],
 'fire-in-dwarf-hole':['coin','multiply','dynamite','bag','chest','miner'],
};
type LandingSlot=Pick<SlotMain,'config'|'bonusSymbol'>&{moneySymbol?:string;profile?:{feature:string}};
export function isFeatureLandingSymbol(slot:LandingSlot,id:string):boolean{
 if(!id)return false;
 if(id===slot.bonusSymbol||id==='wild'||id===slot.config.id+'-wild')return true;
 if(roles[slot.config.id]?.some(role=>id===slot.config.id+'-'+role))return true;
 // Retained shared engines expose their actual collecting/holding money role.
 return id===slot.moneySymbol&&['hold-respin','collector','three-bonus'].includes(slot.profile?.feature||'');
}
export function shouldPumpLanding(slot:LandingSlot,id:string,value=0,cellMultiplier=false):boolean{
 return isFeatureLandingSymbol(slot,id)||(!cellMultiplier&&value>1);
}
