import {ChaosPreviewSlot} from './ChaosPreviewSlot';
import {CHAOS_ART,ChaosLanding,ChaosState,chaosStart,chaosResolve,chaosSymbol as symbol,chaosLandingArt} from './ChaosFeature';
import {CHAOS_PAYS,CHAOS_LINES,CHAOS_BASE_MULTIPLIERS,CHAOS_ADD_VALUES,CHAOS_MULTIPLY_VALUES,chaosBaseWins} from './ChaosRules';
import {SlotConfig,SlotPresentation,SpinResult} from './SlotMain';

// Public rules/paytable are source-backed. Original reel probabilities are not
// public: these are explicit local sampling weights, not original strips/RTP.
const WEIGHTS=[14,14,14,14,14,7,7,7,3];
export class ChaosSlot extends ChaosPreviewSlot {
 readonly hasBonus=true;readonly usesReferencePayouts=true;readonly paylines=CHAOS_LINES;
 readonly bonusCalibrationKey='chaos-crew-x:reel-bank-v1';
 get unlockPriceTenths(){return 1000;}
 readonly presentation:SlotPresentation={evidence:'official-rules',anticipationText:'포스터가 모입니다',triggerText:'카오스 갱 · 보너스',bonusInText:'5개 릴 수집 · 남은 3회',hitText:'고양이 배수 · 라인 당첨',totalWinText:'카오스 갱 · 총 당첨',signature:'해골 더하기 · 고양이 곱하기 · Epic 전체 릴',uiEffect:'숫자 수집 후 5개 릴 합산',soundCue:'featureLand',anticipationHold:.35,hitHold:.25,outHold:.6};
 readonly config:SlotConfig={id:'chaos-crew-x',title:'카오스 갱',subtitle:'CHAOS GANG',tag:'15라인 · 릴별 수집',color:'#242337',accent:'#7bdaca',description:'5×5 · 15라인\n고양이 WILD ×2·×3·×5\n포스터 3개 → 남은 3회 보너스\n해골 더하기 · 고양이 곱하기\nEpic은 전체 릴 · 성공 시 3회 복구\n최대 10,000배에서 즉시 종료',symbols:CHAOS_ART.map((art,i)=>({id:symbol(art),name:art==='cat_wild'?'고양이 WILD':art==='scatter_poster'?'보너스 포스터':art.replace(/_/g,' '),color:'#7bdaca',weight:WEIGHTS[i]||0,payout:CHAOS_PAYS[i]?.[2]||0}))};
 private regular(rng:()=>number){let roll=rng()*WEIGHTS.reduce((a,b)=>a+b,0);for(let i=0;i<WEIGHTS.length;i++){roll-=WEIGHTS[i];if(roll<0)return symbol(CHAOS_ART[i]);}return symbol('tentacle');}
 private base(bet:number,rng:()=>number):SpinResult{
  const board=Array.from({length:25},()=>this.regular(rng)),values=Array(25).fill(0);
  for(let col=0;col<5;col++){
   for(let row=0;row<5;row++)if(rng()<.014){const cell=row*5+col;board[cell]=symbol('cat_wild');values[cell]=CHAOS_BASE_MULTIPLIERS[Math.floor(rng()*3)];}
   if(rng()<.10){const cell=Math.floor(rng()*5)*5+col;board[cell]=this.bonusSymbol;values[cell]=0;}
  }
  return this.evaluateWithValues(board,values,bet);
 }
 evaluateWithValues(board:string[],values:number[],bet:number):SpinResult{
  if(!this.bets.includes(bet))throw Error('Invalid Chaos bet');const wins=chaosBaseWins(board,values,bet);
  return{bet,board:[...board],symbolValues:[...values],wins,payout:wins.reduce((sum,win)=>sum+win.amount,0),presentation:this.presentation};
 }
 evaluate(board:string[],bet:number){if(board.some(id=>id===symbol('cat_wild')))throw Error('Chaos wild requires explicit multiplier');return this.evaluateWithValues(board,Array(25).fill(0),bet);}
 private landings(rng:()=>number):ChaosLanding[]{
  const result:ChaosLanding[]=[];
  // Reel order left to right, cells top to bottom within a reel. Kept explicit
  // for video verification against the help's processing-order wording.
  for(let col=0;col<5;col++)for(let row=0;row<5;row++)if(rng()<.022){
   const kind=rng()<.68?'add':'multiply',values=kind==='add'?CHAOS_ADD_VALUES:CHAOS_MULTIPLY_VALUES;
   const value=values[Math.min(4,Math.floor(rng()*rng()*5))];result.push({cell:row*5+col,kind,value,epic:rng()<.065});
  }
  return result;
 }
 private bonus(base:SpinResult,rng:()=>number):SpinResult{
  const rounds=[base],budget=base.bet*this.maxWin-base.payout;let state:ChaosState=chaosStart();
  while(state.remaining>0){
   if(state.played>=1000)throw Error('Chaos bonus did not converge');
   const landings=this.landings(rng),feature=chaosResolve(state,landings,base.bet,budget),board=Array(25).fill(symbol('inactive_mark'));
   landings.forEach(landing=>board[landing.cell]=chaosLandingArt(landing));state=feature.after;const award=feature.collection?.award;
   rounds.push({bet:base.bet,board,wins:award?[award]:[],payout:award?.amount||0,chaosFeature:feature,freeSpinsAdded:feature.added||undefined,freeSpinsRemaining:state.remaining,roundLabel:`카오스 수집 · ${state.played}회 · 남은 ${state.remaining}회`,presentation:this.presentation});
  }
  return{bet:base.bet,board:[...rounds[rounds.length-1].board],wins:rounds.flatMap(round=>round.wins),payout:rounds.reduce((sum,round)=>sum+round.payout,0),rounds,freeSpinsAwarded:3,featureName:'카오스 갱 · 릴 수집',bonusEndReason:rounds[rounds.length-1].chaosFeature?.collection?.capReached?'max-win':'spins-exhausted',presentation:this.presentation};
 }
 spin(bet:number,rng:()=>number=Math.random):SpinResult{
  if(!this.bets.includes(bet))throw Error('Invalid Chaos bet');const base=this.base(bet,rng);
  return base.payout<bet*this.maxWin&&base.board.filter(id=>id===this.bonusSymbol).length>=3?this.bonus(base,rng):base;
 }
 demoSpin(bet:number){let seed=731234;return this.spin(bet,()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;});}
 bonusDemoSpin(bet:number){
  let seed=152991;const rng=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;},base=this.base(bet,rng);
  base.board=base.board.map(id=>id===this.bonusSymbol?symbol('eight_ball'):id);[0,7,14].forEach(cell=>{base.board[cell]=this.bonusSymbol;base.symbolValues![cell]=0;});
  return this.bonus(this.evaluateWithValues(base.board,base.symbolValues!,bet),rng);
 }
}
